import subprocess, re, sys
types = ["None","Text","TextSymbol","TextPunctuation","TextWhitespace","Keyword","Name","Literal","Comment","Generic","Punctuation","Operator","Error","LiteralNumberInteger","NameBuiltin","CommentSingle","GenericStrong","LiteralString"]
chars="abcdefghijklmnopqrst"
rules = ['    <rule pattern="%s"><token type="%s"/></rule>' % (c,t) for c,t in zip(chars,types)]
open('/workspace/probe2.lx','w').write('<lexer>\n<config><name>Probe2</name></config>\n<rules>\n  <state name="root">\n'+"\n".join(rules)+'\n  </state>\n</rules>\n</lexer>\n')
inp=b'abcdefghijklmnopqrst'
def parse(out):
    segs=[];pos=0
    for m in re.finditer(r'\x1b\[[0-9;]*m', out):
        if m.start()>pos: segs.append(('TEXT', out[pos:m.start()]))
        segs.append(('SEQ', m.group())); pos=m.end()
    if pos<len(out): segs.append(('TEXT', out[pos:]))
    return segs
CH=18
def probe(colors, formatter):
    res=[]
    for start in range(0,len(colors),CH):
        chunk=colors[start:start+CH]
        if len(chunk)<CH: chunk = chunk + [chunk[-1]]*(CH-len(chunk))
        entries = "\n".join('  <entry type="%s" style="bg:%s"/>'%(t,'#%02x%02x%02x'%c) for t,c in zip(types,chunk))
        open('/workspace/probestyle.xml','w').write('<style name="p">\n'+entries+'\n</style>\n')
        r=subprocess.run(['./executable','-f',formatter,'-s','/workspace/probestyle.xml','-l','/workspace/probe2.lx'],capture_output=True,input=inp)
        out=r.stdout.decode()
        segs=parse(out)
        idx=0; cur=[]; m={}
        for kind,val in segs:
            if kind=='SEQ':
                if val=='\x1b[0m': cur=[]
                else: cur.append(val)
            else:
                for ch in val:
                    if idx<CH: m[idx]=cur
                    idx+=1
        for i in range(len(chunk)):
            res.append((chunk[i], tuple(m.get(i,[]))))
    return res
