import json
inh=json.load(open('/tmp/inherit83.json'))
children={t:[x for x in inh[t] if x!=t] for t in inh}
def parent(t, children):
    cands=[u for u,c in children.items() if t in c and u!=t]
    if not cands: return None
    def depth(u, seen=None):
        seen=seen or set()
        if u in seen: return 0
        seen=seen|{u}
        p=parent(u, children)
        return 1+ (depth(p,seen) if p else 0)
    return max(cands, key=depth)
