import json
order=json.load(open('/tmp/tokendata.json'))['order']
parents=json.load(open('/tmp/parents.json'))
t2c=json.load(open('/tmp/type2cls.json'))
# fix pseudo parents
for k in ["Background","PreWrapper","LineLink","LineTableTD","LineTable","LineHighlight","LineNumbersTable","LineNumbers","Line"]:
    parents[k]=None
# order: Text first (as root), then pseudo, then the rest grouped
order = ["Text"] + [t for t in ["Background","PreWrapper","LineLink","LineTableTD","LineTable","LineHighlight","LineNumbersTable","LineNumbers","Line"]] + [t for t in order if t not in ("Text","Background","PreWrapper","LineLink","LineTableTD","LineTable","LineHighlight","LineNumbersTable","LineNumbers","Line")]
lines=[]
lines.append("package token\n")
lines.append("// TokenType identifies the type of a token.")
lines.append("type TokenType int\n")
lines.append("// Token types.\nconst (\n")
for i,t in enumerate(order):
    lines.append("\t%s TokenType = %d" % (t, i))
lines.append(")\n")
lines.append("// tokenTypeNames maps token types to their names.")
lines.append("var tokenTypeNames = map[TokenType]string{")
for t in order:
    lines.append('\t%s: "%s",' % (t,t))
lines.append("}\n")
lines.append("// tokenTypeByNames maps names to token types.")
lines.append("var tokenTypeByName = map[string]TokenType{")
for t in order:
    lines.append('"%s": %s,' % (t,t))
lines.append("}\n")
lines.append("// CSS classes for token types.")
lines.append("var cssClasses = map[TokenType]string{")
for t in order:
    if t in t2c:
        lines.append('%s: "%s",' % (t,t2c[t]))
lines.append("}\n")
lines.append("// parents maps token types to their parent token type.")
lines.append("var parents = map[TokenType]TokenType{")
for t in order:
    p=parents.get(t)
    if p: lines.append('%s: %s,' % (t,p))
lines.append("}\n")
lines.append("""
// String returns the name of the token type.
func (t TokenType) String() string {
	if n, ok := tokenTypeNames[t]; ok {
		return n
	}
	return "Unknown"
}

// Name returns the name of the token type.
func (t TokenType) Name() string { return t.String() }

// SubCategory returns the parent category of the token type.
func (t TokenType) SubCategory() TokenType {
	if p, ok := parents[t]; ok {
		return p
	}
	return t
}

// IsSubCategory reports whether the token type belongs to the given category.
func (t TokenType) Category() TokenType {
	for t != Text && t != Background {
		p := t.SubCategory()
		if p == t {
			break
		}
		t = p
	}
	return t
}

// CSSClass returns the CSS class name for the token type.
func (t TokenType) CSSClass() string {
	if c, ok := cssClasses[t]; ok {
		return c
	}
	return ""
}

// FromName returns the token type for a name.
func FromName(name string) (TokenType, bool) {
	t, ok := tokenTypeByName[name]
	return t, ok
}
""")
