package colour

import (
	"fmt"
	"math"
	"strconv"
	"strings"
)

// Colour is an RGB colour.
type Colour int

// ParseColour parses a colour from a hex string like "#ff0000" or "#fff".
func ParseColour(s string) (Colour, bool) {
	s = strings.TrimSpace(s)
	if !strings.HasPrefix(s, "#") {
		return 0, false
	}
	h := s[1:]
	switch len(h) {
	case 3:
		v, err := strconv.ParseUint(h, 16, 32)
		if err != nil {
			return 0, false
		}
		r := (v >> 8) & 0xf
		g := (v >> 4) & 0xf
		b := v & 0xf
		return Colour(r<<20 | r<<16 | g<<12 | g<<8 | b<<4 | b), true
	case 6:
		v, err := strconv.ParseUint(h, 16, 32)
		if err != nil {
			return 0, false
		}
		return Colour(v), true
	}
	return 0, false
}

// Red returns the red component.
func (c Colour) Red() int { return int(c>>16) & 0xff }

// Green returns the green component.
func (c Colour) Green() int { return int(c>>8) & 0xff }

// Blue returns the blue component.
func (c Colour) Blue() int { return int(c) & 0xff }

// Hex returns the colour as a hex string.
func (c Colour) Hex() string {
	return fmt.Sprintf("#%02x%02x%02x", c.Red(), c.Green(), c.Blue())
}

// IsZero reports whether the colour is unset.
func (c Colour) IsZero() bool { return c == 0 }

// ANSI256 returns the closest ANSI-256 colour index.
func (c Colour) ANSI256() int {
	if v, ok := ansi256ByColour[c]; ok {
		return v
	}
	return nearestANSI256(c)
}

// ANSI16 returns the closest ANSI-16 colour index.
func (c Colour) ANSI16() int {
	if v, ok := ansi16ByColour[c]; ok {
		return v
	}
	return nearestANSI16(c)
