actions.command:
cd /workspace; timeout 175 python3 - <<'PYEOF'
import subprocess, re, json
allt=json.load(open('/tmp/alltypes.json'))
inp=open('/tmp/in83.txt','rb').read()
styles=json.load(open('/tmp/registry.json'))['styles']
def parse(out):
    segs=[];pos=0
    for m in re.finditer(r'\x1b\[[0-9;]*m', out):
        if m.start()>pos: segs.append(('T', out[pos:m.start()]))
        segs.append(('S', m.group())); pos=m.end()
    if pos<len(out): segs.append(('T', out[pos:]))
    return segs
res={}
bad=[]
for s in styles:
    r=subprocess.run(['./executable','-f','terminal16m','-s',s,'-l','/workspace/probe83.lx'],capture_output=True,input=inp)
    if r.stderr: print("ERR",s,r.stderr[:200]); continue
    segs=parse(r.stdout.decode())
    idx=0; cur=[]; m={}
    for k,v in segs:
        if k=='S':
            if v=='\x1b[0m': cur=[]
            else: cur.append(v)
        else:
            for ch in v:
                if idx<len(allt): m[allt[idx]]=''.join(x[2:-1] for x in cur)
                idx+=1
    res[s]=m
json.dump(res, open('/tmp/styleansi.json','w'), indent=1)
print("done", len(res))
for s in list(res)[:2]:
    for t in ['Text','None','Error','Keyword','Comment']:
        print(s,t,res[s][t])
PYEOF

