import json
styles=json.load(open('/tmp/registry.json'))['styles']
css=json.load(open('/tmp/styles_css.json'))['styles']
ansi=json.load(open('/tmp/styleansi.json'))
allt=json.load(open('/tmp/alltypes.json'))
def rgb(h):
    c=h[1:]
    return '38;2;%d;%d;%d'%(int(c[0:2],16),int(c[2:4],16),int(c[4:6],16))
bad=[]
for s in styles:
    if s=='swapoff': continue
    e=css[s]; bg=e['Background']
    exp_bg=[]
    if bg['bold']: exp_bg.append('1')
    if bg['underline']: exp_bg.append('4')
    if bg['italic']: exp_bg.append('3')
    if bg['color']: exp_bg.append(rgb(bg['color']))
    expbg=';'.join(exp_bg)
    mapping={'None':'','TextSymbol':'','TextPunctuation':'','Text':'','LiteralOther':'Literal','LiteralStringAtom':'LiteralString'}
    for t,src in mapping.items():
        if src:
            se=e.get(src,{'color':None,'bg':None,'bold':False,'italic':False,'underline':False})
            exp=[]
            if se['bold']: exp.append('1')
            if se['underline']: exp.append('4')
            if se['italic']: exp.append('3')
            if se['color']: exp.append(rgb(se['color']))
            expv=';'.join(exp)
        else:
            expv=expbg
        v=ansi[s].get(t,'')
        if v!=expv: bad.append((s,t,v,expv))
print("mismatches:", len(bad), bad[:10])
PYEOF"}

