package style

import (
	"strings"

	"chroma/internal/colour"
	"chroma/internal/token"
)

// StyleEntry is a single style entry.
type StyleEntry struct {
	Colour     colour.Colour
	Background colour.Colour
	Bold       bool
	Italic     bool
	Underline  bool
}

// IsZero reports whether the entry is empty.
func (e StyleEntry) IsZero() bool {
	return e.Colour.IsZero() && e.Background.IsZero() && !e.Bold && !e.Italic && !e.Underline
}

// Style is a set of style entries.
type Style struct {
	Name    string
	entries map[token.TokenType]StyleEntry
}

// New creates a style from a map of token types to entries.
func New(name string, entries map[token.TokenType]StyleEntry) *Style {
	e := map[token.TokenType]StyleEntry{}
	for t, v := range entries {
		if !v.IsZero() {
			e[t] = v
		}
	}
	return &Style{Name: name, entries: e}
}

// Get returns the entry for a token type, walking up the token type hierarchy.
func (s *Style) Get(t token.TokenType) StyleEntry {
	cur := t
	for {
		if e, ok := s.entries[cur]; ok {
			return e
		}
		if cur == token.Text {
			break
		}
		p := cur.SubCategory()
		if p == cur {
			break
		}
		cur = p
	}
	return StyleEntry{}
}

// Entries returns the explicitly defined entries.
func (s *Style) Entries() map[token.TokenType]StyleEntry { return s.entries }

// ParseStyleSpec parses a compact style entry spec: "fg/bg/flags".
func ParseStyleSpec(spec string) StyleEntry {
	var e StyleEntry
	parts := strings.SplitN(spec, "/", 3)
	if len(parts) > 0 && parts[0] != "" {
		if c, ok := colour.ParseColour("#" + parts[0]); ok {
			e.Colour = c
		}
	}
	if len(parts) > 1 && parts[1] != "" {
		if c, ok := colour.ParseColour("#" + parts[1]); ok {
			e.Background = c
		}
	}
	if len(parts) > 2 {
		if strings.Contains(parts[2], "b") {
			e.Bold = true
		}
		if strings.Contains(parts[2], "i") {
			e.Italic = true
		}
		if strings.Contains(parts[2], "u") {
			e.Underline = true
		}
	}
	return e
}
GOEOF
