    parts=[]
    for t in sorted(ents):
        parts.append("%s=%s"%(t,ents[t]))
    lines.append('\t"%s": map[string]string{' % s)
    for p in parts:
        lines.append('\t\t"%s",'%p.replace('=',': '))
    lines.append('\t},')
lines.append("}\n")
lines.append("""
// Names returns the names of the built-in styles.
var styleNames = []string{""")
lines.append(", ".join('"%s"'%s for s in styles))
lines.append("}")

lines.append("""
func init() {
	for _, name := range styleNames {
		entries := map[token.TokenType]StyleEntry{}
		for _, spec := range styleData[name] {
			i := strings.Index(spec, ": ")
			if i < 0 {
				continue
			}
