// Terminal formats tokens using ANSI escape sequences.
type Terminal struct {
	Mode string // terminal8, terminal16, terminal256, terminal16m
}

// Format writes the tokens to w.
func (f *Terminal) Format(w *Writer, s *style.Style, tokens []Token) {
	bg := s.Get(token.Background)
	for _, t := range tokens {
		e := s.Get(t.Type)
		fg := e.Colour
		bold, italic, underline := e.Bold, e.Italic, e.Underline
		if fg.IsZero() {
			fg = bg.Colour
		}
		if !bold {
			bold = bg.Bold
		}
		if !italic {
			italic = bg.Italic
		}
		if !underline {
			underline = bg.Underline
		}
		if fg.IsZero() && e.Background.IsZero() && !bold && !italic && !underline {
			w.WriteString(t.Value)
			continue
		}
		var seq string
		if bold {
			seq += "\x1b[1m"
		}
		if underline {
			seq += "\x1b[4m"
		}
		if italic {
			seq += "\x1b[3m"
		}
		if !fg.IsZero() {
			seq += fg.FgSequence(f.Mode)
		}
		if !e.Background.IsZero() {
			seq += e.Background.BgSequence(f.Mode)
		}
		w.WriteString(seq)
		w.WriteString(t.Value)
		w.WriteString("\x1b[0m")
	}
}
