package formatter

import (
	"strconv"
	"strings"
)

// Noop writes the raw token values.
func Noop(w *Writer, tokens []Token) {
	for _, t := range tokens {
		w.WriteString(t.Value)
	}
}

// Tokens writes tokens in the Go representation form.
func Tokens(w *Writer, tokens []Token) {
	for _, t := range tokens {
		w.WriteString("&Token{")
		w.WriteString(t.Type.String())
		w.WriteString(", ")
		w.WriteString(strconv.Quote(t.Value))
		w.WriteString("}\n")
	}
}

// JSON writes tokens as a JSON array.
func JSON(w *Writer, tokens []Token) {
	w.WriteString("[\n")
	for i, t := range tokens {
		w.WriteString("  {\"type\":")
		w.WriteString(strconv.Quote(t.Type.String()))
		w.WriteString(",\"value\":")
		w.WriteString(strconv.Quote(t.Value))
		w.WriteString("}")
		if i < len(tokens)-1 {
			w.WriteString(",")
		}
		w.WriteString("\n")
	}
	w.WriteString("]\n")
}

// IndentTabs replaces tabs with spaces.
func IndentTabs(s string, tabWidth int) string {
	if tabWidth <= 0 {
		return s
	}
	return strings.ReplaceAll(s, "\t", strings.Repeat(" ", tabWidth))
}
