package lexer

import (
	"regexp"
	"strings"

	"chroma/internal/token"
)

// MutatorKind identifies a state stack mutation.
type MutatorKind int

// Mutator kinds.
const (
	MutPush MutatorKind = iota
	MutPop
	MutPopN
	MutPushN
)

// Mutator mutates the state stack.
type Mutator struct {
	Kind  MutatorKind
	State string
	N     int
}

// Push returns a push mutator.
func Push(state string) Mutator { return Mutator{Kind: MutPush, State: state} }

// Pop returns a pop mutator.
func Pop() Mutator { return Mutator{Kind: MutPop} }

// PopN returns a pop n mutator.
func PopN(n int) Mutator { return Mutator{Kind: MutPopN, N: n} }

// Rule is a single lexer rule.
type Rule struct {
	Pattern string
	Type    token.TokenType
	// Groups is the list of token types for a ByGroups emitter.
	ByGroups []token.TokenType
	// Mutators applied after the token is emitted.
	Mutators []Mutator
	// Callback is a custom action. When non-nil it receives the match groups.
	Callback func(m []string, l *LexerState)
	// Include is the name of a state to include inline.
	Include string
	// Combined marks a combined state definition.
	Combined bool
}

// LexerState is the current lexer state.
type LexerState struct {
	Lexer *Lexer
	Stack []string
	Pos   int
	Input string
	// Iterator for tokens emitted so far
	Tokens *[]Token
}

// Lexer is a state machine lexer.
type Lexer struct {
	Name    string
	Aliases []string
	Files   []string
	Mimes   []string
	States  map[string][]Rule
	// CaseInsensitive makes all patterns case insensitive.
	CaseInsensitive bool
	// DotAll enables the (?s) flag for all patterns.
	DotAll bool
	compiled map[string][]compiledRule
}

type compiledRule struct {
	re  *regexp.Regexp
	rule *Rule
	idx int
}

// Compile prepares the lexer for use.
func (l *Lexer) Compile() error {
	l.compiled = map[string][]compiledRule{}
	flags := "(?m)"
	if l.CaseInsensitive {
		flags = "(?mi)"
	}
	if l.DotAll {
		flags += "s"
	}
	var walk func(name string, seen map[string]bool) ([]compiledRule, error)
	walk = func(name string, seen map[string]bool) ([]compiledRule, error) {
		if crs, ok := l.compiled[name]; ok {
			return crs, nil
		}
		if seen[name] {
			return nil, nil
		}
		seen[name] = true
		var out []compiledRule
		for _, r := range l.States[name] {
			if r.Include != "" {
				sub, err := walk(r.Include, seen)
				if err != nil {
