package lexer

import (
	"path/filepath"
	"sort"
	"strings"

	"chroma/internal/token"
)

var (
	registry    = map[string]*Lexer{}
	byAlias    = map[string]*Lexer{}
	nameList   []string
	fallbackLx *Lexer
)

func init() {
	for _, m := range lexerMetas {
		if m.Name == "plaintext" {
			continue
		}
		l := &Lexer{Name: m.Name, Aliases: m.Aliases, Files: m.Files, Mimes: m.Mimes, States: map[string][]Rule{}}
		registry[m.Name] = l
		nameList = append(nameList, m.Name)
		for _, a := range m.Aliases {
			byAlias[a] = l
		}
	}
	fallbackLx = &Lexer{
		Name:   "fallback",
		States: map[string][]Rule{"root": {{Pattern: `.+`, Type: token.Text}, {Pattern: `\n`, Type: token.Text}}},
	}
}

// Names returns all lexer names.
func Names() []string { return nameList }

// Get returns a lexer by name or alias.
func Get(name string) *Lexer {
	if l, ok := registry[name]; ok {
		return l
	}
	if l, ok := byAlias[name]; ok {
		return l
	}
	return nil
}

// Match returns a lexer matching a filename.
func Match(filename string) *Lexer {
	base := filepath.Base(filename)
	for _, n := range nameList {
		l := registry[n]
		for _, f := range l.Files {
			if ok, _ := filepath.Match(f, base); ok {
				return l
			}
		}
	}
	return nil
}

// Fallback returns the fallback lexer.
func Fallback() *Lexer { return fallbackLx }

// SortedNames returns the lexer names sorted.
func SortedNames() []string {
	out := append([]string{}, nameList...)
	sort.Strings(out)
	return out
}

// LexerName returns the canonical name for a lexer.
func LexerName(l *Lexer) string {
	if l == nil {
		return "fallback"
	}
	if l.Name != "" {
		return l.Name
	}
	return "fallback"
}

// IsEmpty reports whether a lexer has no rules.
func IsEmpty(l *Lexer) bool {
	if l == nil {
		return true
	}
	return len(l.States) == 0
}

// Coalesce merges adjacent tokens with the same type.
func Coalesce(tokens []Token) []Token {
	if len(tokens) == 0 {
		return tokens
	}
	out := []Token{tokens[0]}
	for _, t := range tokens[1:] {
		if out[len(out)-1].Type == t.Type {
			out[len(out)-1].Value += t.Value
			continue
		}
		out = append(out, t)
	}
	return out
}

// Analyse tries to detect the lexer from the content.
func Analyse(text string) *Lexer {
	if l := analyseShebang(text); l != nil {
		return l
	}
	var best *Lexer
	bestScore := 0.0
	for _, l := range analysers {
		score := l.fn(text)
		if score > bestScore {
			bestScore = score
			best = l.lx
		}
	}
	if bestScore > 0.2 {
		return best
	}
	return nil
}

type analyser struct {
	lx *Lexer
	fn func(string) float64
}

var analysers []analyser

func registerAnalyser(l *Lexer, fn func(string) float64) {
	analysers = append(analysers, analyser{lx: l, fn: fn})
}

func analyseShebang(text string) *Lexer {
	if !strings.HasPrefix(text, "#!") {
		return nil
	}
	line := text
	if i := strings.IndexByte(line, '\n'); i >= 0 {
		line = line[:i]
	}
	for _, n := range nameList {
		l := registry[n]
		for _, f := range l.Files {
			_ = f
		}
	}
	return nil
}
