const (
	exitUsage = 80
)

var formattersList = []string{"html", "json", "noop", "svg", "terminal", "terminal16", "terminal16m", "terminal256", "terminal8", "tokens"}

type options struct {
	files     []string
	unbuffered bool
	trace     bool
	check     bool
	filename  string
	fail      bool
	lexer     string
	sty       string
	formatter string
	json      bool
	html      bool
	svg       bool
	htmlPrefix string
	htmlStyles bool
	htmlAllStyles bool
	htmlOnly  bool
	htmlInlineStyles bool
