	htmlLines bool
	htmlLinesTable bool
	htmlLinesStyle string
	htmlHighlight string
	htmlHighlightStyle string
	htmlBaseLine int
	htmlPreventSurroundingPre bool
	htmlLinkableLines bool
}

func main() {
	os.Exit(run(os.Args[1:]))
}

func fatalf(format string, args ...interface{}) {
	fmt.Fprintf(os.Stderr, "%s: error: %s\n", filepath.Base(os.Args[0]), fmt.Sprintf(format, args...))
}

func run(args []string) int {
	o := &options{formatter: "terminal", sty: "swapoff", lexer: "autodetect", htmlTabWidth: 8, htmlBaseLine: 1}
	rest, err := parseArgs(args, o)
	if err != nil {
		fatalf("%s", err.Error())
		return exitUsage
	}
	if o.help {
		fmt.Print(helpText())
		return 0
	}
	if o.version {
		fmt.Println("?-?-?")
		return 0
	}
	if o.list {
		return doList()
	}
	o.files = rest
	for _, f := range o.files {
		if st, err := os.Stat(f); err != nil {
			fatalf("[%s]: stat %s: no such file or directory", "[<files> ...]", f)
			return exitUsage
		} else if st.IsDir() {
			fatalf("[%s]: %q exists but is a directory", "[<files> ...]", f)
			return exitUsage
		}
	}
	if o.html {
		o.formatter = "html"
	}
	if o.json {
		o.formatter = "json"
	}
	if o.svg {
		o.formatter = "svg"
	}
	if !validFormatter(o.formatter) {
		fatalf("--formatter must be one of %s but got %q", formatterEnumList(), o.formatter)
		return exitUsage
	}
	st, err := resolveStyle(o.sty)
	if err != nil {
		fatalf("%s", err.Error())
		return 1
	}
	lx, err := resolveLexer(o.lexer, o)
	if err != nil {
		fatalf("%s", err.Error())
		return 1
	}
	// Read input
	var text string
	if len(o.files) > 0 {
		var sb strings.Builder
		for _, f := range o.files {
			data, err := os.ReadFile(f)
			if err != nil {
				fatalf("%s", err.Error())
				return 1
			}
			sb.WriteString(string(data))
		}
		text = sb.String()
	} else {
		data, err := readAll(os.Stdin)
		if err != nil {
			fatalf("%s", err.Error())
			return 1
		}
		text = data
	}
	if lx == nil || lexer.IsEmpty(lx) {
		if o.fail || invokedAsLessFilter() {
			return 1
		}
		lx = lexer.Fallback()
	}
	tokens := lexer.Coalesce(lx.Tokenise(text))
	// Format
	w := &formatter.Writer{}
	switch o.formatter {
	case "noop":
		formatter.Noop(w, tokens)
	case "tokens":
		formatter.Tokens(w, tokens)
	case "json":
		formatter.JSON(w, tokens)
	case "terminal", "terminal8", "terminal16", "terminal256", "terminal16m":
		mode := o.formatter
		if mode == "terminal" {
			mode = "terminal8"
		}
		(&formatter.Terminal{Mode: mode}).Format(w, st, tokens)
	case "html":
		err = formatter.HTML(w, st, tokens, htmlOptions(o))
	case "svg":
		err = formatter.SVG(w, st, tokens)
	}
