		fatalf("%s", err.Error())
		return 1
	}
	if o.check {
		for _, t := range tokens {
			if t.Type == token.Error {
				return 1
			}
		}
		return 0
	}
	os.Stdout.WriteString(w.String())
	return 0
}

func readAll(f *os.File) (string, error) {
	var sb strings.Builder
	buf := make([]byte, 32*1024)
	for {
		n, err := f.Read(buf)
		if n > 0 {
			sb.WriteString(string(buf[:n]))
		}
		if err != nil {
			if err.Error() == "EOF" {
				return sb.String(), nil
			}
			return sb.String(), err
		}
	}
}

func invokedAsLessFilter() bool {
	return filepath.Base(os.Args[0]) == ".lessfilter"
}

func validFormatter(f string) bool {
	for _, n := range formattersList {
		if n == f {
			return true
		}
	}
	return false
}

func formatterEnumList() string {
	var sb strings.Builder
	for i, n := range formattersList {
		if i > 0 {
			sb.WriteString(",")
		}
		sb.WriteString(strconv.Quote(n))
	}
	return sb.String()
}

func helpText() string {
	data, _ := assets.ReadFile("help.txt")
	return fmt.Sprintf(string(data), filepath.Base(os.Args[0]))
