		if len(lx.Aliases) > 0 {
			fmt.Printf("    aliases: %s\n", strings.Join(lx.Aliases, " "))
		}
		if len(lx.Files) > 0 {
			fmt.Printf("    filenames: %s\n", strings.Join(lx.Files, " "))
		}
		if len(lx.Mimes) > 0 {
			fmt.Printf("    mimetypes: %s\n", strings.Join(lx.Mimes, " "))
		}
	}
	fmt.Println()
	fmt.Printf("styles: %s\n", strings.Join(style.Names(), " "))
	fmt.Printf("formatters: %s\n", strings.Join(formattersList, " "))
	return 0
}

func resolveStyle(name string) (*style.Style, error) {
	if s, ok := style.Get(name); ok {
		return s, nil
	}
	data, err := os.ReadFile(name)
	if err != nil {
		return nil, err
	}
	return style.LoadXML(string(data))
}

func resolveLexer(name string, o *options) (*lexer.Lexer, error) {
	if l := lexer.Get(name); l != nil {
		return l, nil
	}
	if l := lexer.Match(name); l != nil {
		return l, nil
	}
	data, err := os.ReadFile(name)
	if err != nil {
		if os.IsNotExist(err) {
			return nil, nil
		}
		return nil, err
	}
	return lexer.LoadXML(string(data))
}

func htmlOptions(o *options) formatter.HTMLOptions {
	return formatter.HTMLOptions{
		Prefix:          o.htmlPrefix,
		Standalone:      !o.htmlOnly,
		WithClasses:     !o.htmlInlineStyles,
		InlineStyles:    o.htmlInlineStyles,
		LineNumbers:     o.htmlLines,
		LineNumbersInTable: o.htmlLines && o.htmlLinesTable,
		LinkableLineNumbers: o.htmlLinkableLines,
		TabWidth:        o.htmlTabWidth,
		BaseLine:        o.htmlBaseLine,
		PreventSurroundingPre: o.htmlPreventSurroundingPre,
		HighlightRanges: o.htmlHighlight,
		HighlightStyle:  o.htmlHighlightStyle,
		LinesStyle:      o.htmlLinesStyle,
		Styles:          o.htmlStyles,
		AllStyles:       o.htmlAllStyles,
	}
}
