	if err != nil {
		fail("%s", err.Error())
		return 1
	}
	os.Stdout.WriteString(w.String())
	return 0
}

func toFormatterTokens(in []lexer.Token) []formatter.Token {
	out := make([]formatter.Token, len(in))
	for i, t := range in {
		out[i] = formatter.Token{Type: t.Type, Value: t.Value}
	}
	return out
}

func writeCSS(o *options, st *style.Style) int {
	w := &formatter.Writer{}
	formatter.WriteCSS(w, st, formatter.CSSOptions{
		Standalone: o.htmlAllStyles,
		LineNumbers: o.htmlLines,
		Prefix:     o.htmlPrefix,
		TabWidth:   o.htmlTabWidth,
	})
	os.Stdout.WriteString(w.String())
	return 0
}

func readInput(files []string) (string, error) {
	if len(files) > 0 {
		var sb strings.Builder
		for _, f := range files {
			fh, err := os.Open(f)
			if err != nil {
				return "", err
			}
			data, err := io.ReadAll(fh)
			fh.Close()
			if err != nil {
				return "", err
			}
			sb.WriteString(string(data))
		}
		return sb.String(), nil
	}
	data, err := io.ReadAll(os.Stdin)
	if err != nil {
		return "", err
	}
	return string(data), nil
}

func invokedAsLessFilter() bool { return prog() == ".lessfilter" }

func validFormatter(f string) bool {
	for _, n := range formattersList {
		if n == f {
			return true
		}
	}
	return false
}

func formatterEnumList() string {
	var sb strings.Builder
	for i, n := range formattersList {
		if i > 0 {
			sb.WriteString(",")
		}
		sb.WriteString(strconv.Quote(n))
	}
	return sb.String()
}

func helpText() string {
	data, _ := assets.ReadFile("help.txt")
	return fmt.Sprintf(string(data), prog())
}

func doList() int {
	fmt.Println("lexers:")
	for _, name := range lexer.SortedNames() {
		lx := lexer.Get(name)
		fmt.Printf("  %s\n", name)
		if len(lx.Aliases) > 0 {
			fmt.Printf("    aliases: %s\n", strings.Join(lx.Aliases, " "))
		}
		if len(lx.Files) > 0 {
			fmt.Printf("    filenames: %s\n", strings.Join(lx.Files, " "))
		}
		if len(lx.Mimes) > 0 {
			fmt.Printf("    mimetypes: %s\n", strings.Join(lx.Mimes, " "))
		}
	}
	fmt.Println()
	fmt.Printf("styles: %s\n", strings.Join(style.Names(), " "))
	fmt.Printf("formatters: %s\n", strings.Join(formattersList, " "))
	return 0
}

func resolveStyle(name string) (*style.Style, error) {
	if s, ok := style.Get(name); ok {
		return s, nil
	}
	data, err := os.ReadFile(name)
	if err != nil {
		return nil, err
	}
	return style.LoadXML(string(data))
}

func resolveLexer(name string) (*lexer.Lexer, error) {
	if l := lexer.Get(name); l != nil {
		return l, nil
	}
	if l := lexer.Match(name); l != nil {
		return l, nil
	}
	data, err := os.ReadFile(name)
	if err != nil {
		if os.IsNotExist(err) {
			return nil, nil
		}
		return nil, err
	}
	return lexer.LoadXML(string(data))
}
