	add(flagDef{name: "html-lines-style", hasArg: true, setString: func(o *options, v string) { o.htmlLinesStyle = v }})
	add(flagDef{name: "html-highlight", hasArg: true, setString: func(o *options, v string) { o.htmlHighlight = v }})
	add(flagDef{name: "html-highlight-style", hasArg: true, setString: func(o *options, v string) { o.htmlHighlightStyle = v }})
