	add(flagDef{name: "html-inline-styles", setBool: func(o *options) { o.htmlInlineStyles = true }})
	add(flagDef{name: "html-tab-width", hasArg: true, setInt: func(o *options, v int) { o.htmlTabWidth = v }})
	add(flagDef{name: "html-lines", setBool: func(o *options) { o.htmlLines = true }})
	add(flagDef{name: "html-lines-table", setBool: func(o *options) { o.htmlLinesTable = true }})
	add(flagDef{name: "html-lines-style", hasArg: true, setString: func(o *options, v string) { o.htmlLinesStyle = v }})
	add(flagDef{name: "html-highlight", hasArg: true, setString: func(o *options, v string) { o.htmlHighlight = v }})
	add(flagDef{name: "html-highlight-style", hasArg: true, setString: func(o *options, v string) { o.htmlHighlightStyle = v }})
	add(flagDef{name: "html-base-line", hasArg: true, setInt: func(o *options, v int) { o.htmlBaseLine = v }})
	add(flagDef{name: "html-prevent-surrounding-pre", setBool: func(o *options) { o.htmlPreventSurroundingPre = true }})
	add(flagDef{name: "html-linkable-lines", setBool: func(o *options) { o.htmlLinkableLines = true }})
	return defs
}

// parseArgs parses command line arguments.
func parseArgs(args []string, o *options) ([]string, error) {
	var rest []string
	i := 0
	for i < len(args) {
		a := args[i]
		i++
		switch {
		case a == "--":
			rest = append(rest, args[i:]...)
			i = len(args)
		case strings.HasPrefix(a, "--"):
			body := a[2:]
			name := body
			value := ""
			hasValue := false
			if j := strings.IndexByte(body, '='); j >= 0 {
				name = body[:j]
				value = body[j+1:]
				hasValue = true
			}
			def := findLong(name)
			if def == nil {
				return nil, fmt.Errorf("unknown flag --%s", name)
			}
			if def.hasArg {
				if !hasValue {
					if i >= len(args) {
						return nil, fmt.Errorf("expected argument for flag --%s", name)
					}
					value = args[i]
					i++
				}
				if err := applyValue(def, o, name, value); err != nil {
					return nil, err
				}
			} else {
				if hasValue {
					return nil, fmt.Errorf("unexpected argument for flag --%s", name)
				}
				def.setBool(o)
			}
		case strings.HasPrefix(a, "-") && len(a) > 1:
			short := a[1:2]
			def := findShort(short)
			if def == nil {
				return nil, fmt.Errorf("unknown short flag -%s", short)
			}
			if def.hasArg {
				value := a[2:]
				if value == "" {
					if i >= len(args) {
						return nil, fmt.Errorf("expected argument for flag -%s", short)
					}
					value = args[i]
					i++
				}
				if err := applyValue(def, o, def.name, value); err != nil {
					return nil, err
				}
			} else {
				if len(a) > 2 {
					// combined short flags
					for _, c := range a[1:] {
						d := findShort(string(c))
						if d == nil {
							return nil, fmt.Errorf("unknown short flag -%s", string(c))
						}
						d.setBool(o)
					}
				} else {
					def.setBool(o)
				}
			}
		default:
			rest = append(rest, a)
		}
	}
	return rest, nil
}

func findLong(name string) *flagDef {
	for i := range flagDefs {
		if flagDefs[i].name == name {
			return &flagDefs[i]
		}
	}
	return nil
}

func findShort(short string) *flagDef {
	for i := range flagDefs {
		if flagDefs[i].short == short {
			return &flagDefs[i]
		}
	}
	return nil
}

func applyValue(def *flagDef, o *options, name, value string) error {
	if len(def.enum) > 0 {
		ok := false
		for _, e := range def.enum {
			if e == value {
				ok = true
			}
		}
		if !ok {
			return fmt.Errorf("--%s must be one of %s but got %q", name, enumList(def.enum), value)
		}
	}
	switch def.kind {
	case "int":
		v, err := strconv.Atoi(value)
		if err != nil {
			return fmt.Errorf("--%s must be an integer", name)
		}
		def.setInt(o, v)
	default:
		def.setString(o, value)
	}
	return nil
}

func enumList(values []string) string {
	var sb strings.Builder
	for i, v := range values {
		if i > 0 {
			sb.WriteString(",")
		}
		sb.WriteString(strconv.Quote(v))
	}
	return sb.String()
}
