	m := map[int]bool{}
	if s == "" {
		return m
	}
	for _, part := range strings.Split(s, ",") {
		part = strings.TrimSpace(part)
		if part == "" {
			continue
		}
		var lo, hi int
		if i := strings.IndexByte(part, ':'); i >= 0 {
			fmt.Sscanf(part[:i], "%d", &lo)
			fmt.Sscanf(part[i+1:], "%d", &hi)
		} else {
			fmt.Sscanf(part, "%d", &lo)
			hi = lo
		}
		for i := lo; i <= hi; i++ {
			m[i] = true
		}
	}
	return m
