	TabWidth    int
}

// cssTokenTypes is the order in which token types are written in the CSS.
var cssTokenTypes = []token.TokenType{
	token.Background, token.PreWrapper, token.Other, token.Error, token.LineLink,
	token.LineTableTD, token.LineTable, token.LineHighlight, token.LineNumbersTable,
	token.LineNumbers, token.Line,
	token.Keyword, token.KeywordConstant, token.KeywordDeclaration, token.KeywordNamespace,
	token.KeywordPseudo, token.KeywordReserved, token.KeywordType,
	token.Name, token.NameAttribute, token.NameClass, token.NameConstant, token.NameDecorator,
	token.NameEntity, token.NameException, token.NameLabel, token.NameNamespace, token.NameOther,
	token.NameProperty, token.NameTag, token.NameBuiltin, token.NameBuiltinPseudo,
	token.NameVariable, token.NameVariableClass, token.NameVariableGlobal, token.NameVariableInstance,
	token.NameVariableMagic, token.NameFunction, token.NameFunctionMagic,
	token.Literal, token.LiteralDate, token.LiteralString, token.LiteralStringAffix,
	token.LiteralStringBacktick, token.LiteralStringChar, token.LiteralStringDelimiter,
	token.LiteralStringDoc, token.LiteralStringDouble, token.LiteralStringEscape,
	token.LiteralStringHeredoc, token.LiteralStringInterpol, token.LiteralStringOther,
	token.LiteralStringRegex, token.LiteralStringSingle, token.LiteralStringSymbol,
	token.LiteralNumber, token.LiteralNumberBin, token.LiteralNumberFloat, token.LiteralNumberHex,
	token.LiteralNumberInteger, token.LiteralNumberIntegerLong, token.LiteralNumberOct,
	token.Operator, token.OperatorWord, token.OperatorReserved, token.Punctuation,
	token.Comment, token.CommentHashbang, token.CommentMultiline, token.CommentSingle,
	token.CommentSpecial, token.CommentPreproc, token.CommentPreprocFile,
	token.Generic, token.GenericDeleted, token.GenericEmph, token.GenericError,
	token.GenericHeading, token.GenericInserted, token.GenericOutput, token.GenericPrompt,
	token.GenericStrong, token.GenericSubheading, token.GenericTraceback, token.GenericUnderline,
	token.TextWhitespace,
}

var baseHTMLStyle = map[token.TokenType]style.StyleEntry{
	token.LineHighlight:    {Background: colour.Hex("#e5e5e5")},
	token.LineNumbers:      {Colour: colour.Hex("#7f7f7f")},
	token.LineNumbersTable: {Colour: colour.Hex("#7f7f7f")},
}

var pseudoPrefix = map[token.TokenType]string{
	token.LineLink:         "outline: none; text-decoration: none; color: inherit",
	token.LineTableTD:      "vertical-align: top; padding: 0; margin: 0; border: 0; ",
	token.LineTable:        "border-spacing: 0; padding: 0; margin: 0; border: 0; ",
	token.LineNumbers:      "white-space: pre; -webkit-user-select: none; user-select: none; margin-right: 0.4em; padding: 0 0.4em 0 0.4em;",
	token.LineNumbersTable: "white-space: pre; -webkit-user-select: none; user-select: none; margin-right: 0.4em; padding: 0 0.4em 0 0.4em;",
	token.Line:             "display: flex; ",
}

type htmlWriter struct {
	w            *Writer
	s            *style.Style
	o            HTMLOptions
	prefix       string
	lines        []*htmlLine
	highlightSet map[int]bool
}

type htmlLine struct {
	tokens []Token
}

// WriteCSS writes the CSS for a style.
func WriteCSS(w *Writer, s *style.Style, o CSSOptions) {
	h := &htmlWriter{w: w, s: s, prefix: o.Prefix}
	h.writeCSS(o.TabWidth)
}

// HTML formats tokens as HTML.
func HTML(w *Writer, s *style.Style, tokens []Token, o HTMLOptions) error {
	h := &htmlWriter{w: w, s: s, o: o, prefix: o.Prefix}
	h.format(tokens)
	return nil
}

func (h *htmlWriter) classFor(t token.TokenType) string {
	cls := t.CSSClass()
	if cls == "" {
		return ""
	}
	if h.prefix != "" {
		return h.prefix + cls
	}
	return cls
}

func (h *htmlWriter) entry(t token.TokenType) style.StyleEntry {
	e := h.s.Get(t)
	if e.IsZero() {
		if b, ok := baseHTMLStyle[t]; ok {
			return b
		}
	}
	return e
}

func entryProps(e style.StyleEntry) []string {
	var out []string
	if !e.Colour.IsZero() {
		out = append(out, "color: "+e.Colour.Hex())
	}
	if !e.Background.IsZero() {
		out = append(out, "background-color: "+e.Background.Hex())
	}
	if e.Bold {
		out = append(out, "font-weight: bold")
	}
	if e.Italic {
		out = append(out, "font-style: italic")
	}
	if e.Underline {
		out = append(out, "text-decoration: underline")
	}
	return out
}

func entryInline(e style.StyleEntry) string {
	var out []string
	if !e.Colour.IsZero() {
		out = append(out, "color:"+e.Colour.InlineHex())
	}
	if !e.Background.IsZero() {
		out = append(out, "background-color:"+e.Background.InlineHex())
	}
	if e.Bold {
		out = append(out, "font-weight:bold")
	}
	if e.Italic {
		out = append(out, "font-style:italic")
	}
	if e.Underline {
		out = append(out, "text-decoration:underline")
	}
	return strings.Join(out, ";")
}

func (h *htmlWriter) propsFor(t token.TokenType, tabWidth int) string {
	var parts []string
	switch t {
	case token.Background:
		parts = entryProps(h.s.Get(t))
	case token.PreWrapper:
		parts = append(parts, entryProps(h.s.Get(token.PreWrapper))...)
		parts = append(parts, entryProps(h.s.Get(token.Text))...)
		parts = append(parts, entryProps(h.s.Get(token.Background))...)
	case token.LineLink, token.LineTableTD, token.LineTable, token.LineNumbers, token.LineNumbersTable, token.Line:
		if p, ok := pseudoPrefix[t]; ok {
			parts = append(parts, p)
		}
		parts = append(parts, entryProps(h.entry(t))...)
	case token.LineHighlight:
		parts = entryProps(h.entry(t))
	default:
		e := h.s.Get(t)
		if e.IsZero() {
			return ""
		}
		parts = entryProps(e)
	}
	if len(parts) == 0 {
		return "; "
	}
	return strings.Join(parts, "; ") + "; "
}

func (h *htmlWriter) writeCSS(tabWidth int) {
	w := h.w
	for _, t := range cssTokenTypes {
		props := h.propsFor(t, tabWidth)
		class := h.classFor(t)
		if class == "" {
			continue
		}
		zero := len(props) == 3 // "; "
		if _, isPseudo := pseudoPrefix[t]; !isPseudo && zero && t != token.Background && t != token.PreWrapper && t != token.LineHighlight {
			continue
		}
		name := t.String()
		suffix := ""
		if t == token.PreWrapper {
			suffix = "-webkit-text-size-adjust: none; "
			if tabWidth != 8 {
				suffix = fmt.Sprintf("-moz-tab-size:%d;-o-tab-size:%d;tab-size:%d;-webkit-text-size-adjust: none; ", tabWidth, tabWidth, tabWidth)
			}
		}
		fmt.Fprintf(w, "/* %s */ .%s { %s%s}\n", name, class, props, suffix)
	}
	if h.o.LineNumbers {
		h.writeTargetCSS()
	}
	w.WriteString(fmt.Sprintf("body { color:%s;background-color:%s;; }\n",
		h.s.Get(token.Background).Colour.Hex(), h.s.Get(token.Background).Background.Hex()))
}

func (h *htmlWriter) writeTargetCSS() {
	w := h.w
	bg := h.s.Get(token.Background)
	hl := h.entry(token.LineHighlight)
	for _, t := range []token.TokenType{token.LineNumbers, token.LineNumbersTable} {
		name := t.String()
		if t == token.LineNumbers {
			name = "LineNumbers targeted by URL anchor"
		} else {
			name = "LineNumbersTable targeted by URL anchor"
		}
		var parts []string
		if !bg.Colour.IsZero() {
			parts = append(parts, "color: "+bg.Colour.Hex())
		}
		if !hl.Background.IsZero() {
			parts = append(parts, "background-color: "+hl.Background.Hex())
		}
		fmt.Fprintf(w, "/* %s */ .%s%s:target { %s}\n", name, h.classFor(t), "", strings.Join(parts, "; ")+(" "[:0]))
		if len(parts) > 0 {
			// trailing "; " handled below
		}
	}
}

// HTML body of the formatter.
func (h *htmlWriter) format(tokens []Token) {
	h.lines = splitLines(tokens)
	h.highlightSet = parseHighlight(h.o.Highlight)
	h.write()
}

type htmlLine struct{ tokens []Token }

func splitLines(tokens []Token) []*htmlLine {
	var lines []*htmlLine
	cur := &htmlLine{}
	lines = append(lines, cur)
	for _, t := range tokens {
		v := t.Value
		for {
			i := strings.IndexByte(v, '\n')
			if i < 0 {
				if v != "" {
					cur.tokens = append(cur.tokens, Token{Type: t.Type, Value: v})
				}
				break
			}
			cur.tokens = append(cur.tokens, Token{Type: t.Type, Value: v[:i+1]})
			v = v[i+1:]
			if v == "" {
				break
			}
			cur = &htmlLine{}
			lines = append(lines, cur)
		}
	}
	if len(lines) > 1 && len(lines[len(lines)-1].tokens) == 0 {
		lines = lines[:len(lines)-1]
	}
	return lines
}

func parseHighlight(s string) map[int]bool {
	m := map[int]bool{}
	if s == "" {
		return m
	}
	for _, part := range strings.Split(s, ",") {
		part = strings.TrimSpace(part)
		if part == "" {
			continue
		}
		var lo, hi int
		if i := strings.IndexByte(part, ':'); i >= 0 {
			lo, _ = strconv.Atoi(strings.TrimSpace(part[:i]))
			hi, _ = strconv.Atoi(strings.TrimSpace(part[i+1:]))
		} else {
			lo, _ = strconv.Atoi(part)
			hi = lo
		}
		for i := lo; i <= hi; i++ {
			m[i] = true
		}
	}
	return m
}

func escapeHTML(s string) string {
	r := strings.NewReplacer("&", "&amp;", "<", "&lt;", ">", "&gt;", `"`, "&#34;", "'", "&#39;")
	return r.Replace(s)
}

func (h *htmlWriter) spanOpen(t token.TokenType) string {
	if h.o.InlineStyles {
		e := h.entry(t)
		st := entryInline(e)
		if st == "" {
			return ""
		}
		return "<span style=\"" + st + "\">"
	}
	cls := h.classFor(t)
	if cls == "" {
		return ""
	}
	return "<span class=\"" + cls + "\">"
}

func (h *htmlWriter) hasStyle(t token.TokenType) bool {
	if h.o.InlineStyles {
		return entryInline(h.entry(t)) != ""
	}
	return h.classFor(t) != "" && !h.entry(t).IsZero()
}

func (h *htmlWriter) write() {
	w := h.w
	o := h.o
	// Standalone head
	if o.Standalone {
		w.WriteString("<html>\n")
		if o.InlineStyles {
			w.WriteString("<body style=\"" + entryInline(h.entry(token.Background)) + "\">\n")
		} else {
			w.WriteString("<style type=\"text/css\">\n")
			h.writeCSS(o.TabWidth)
			w.WriteString("</style><body class=\"" + h.prefix + "bg\">\n")
		}
	}
	inner := h.inner()
	if o.Standalone {
		w.WriteString(inner)
		w.WriteString("\n</body>\n</html>\n")
	} else {
		w.WriteString(inner)
	}
}

func (h *htmlWriter) inner() string {
	var b strings.Builder
	h.writeBody(&b)
	return b.String()
}

func (h *htmlWriter) writeBody(b *strings.Builder) {
	o := h.o
	tabWidth := o.TabWidth
	if tabWidth <= 0 {
		tabWidth = 8
	}
	if o.LineNumbersInTable {
		h.writeTable(b, tabWidth)
		return
	}
	if !o.PreventSurroundingPre {
		b.WriteString(h.preOpen(tabWidth))
		b.WriteString("<code>")
	}
	for i, l := range h.lines {
		h.writeLine(b, i, tabWidth, !o.PreventSurroundingPre)
	}
	if !o.PreventSurroundingPre {
		b.WriteString("</code></pre>")
	}
}

func (h *htmlWriter) preOpen(tabWidth int) string {
	if h.o.InlineStyles {
		st := entryInline(h.entry(token.PreWrapper))
		if tabWidth != 8 {
			st += fmt.Sprintf(";-moz-tab-size:%d;-o-tab-size:%d;tab-size:%d", tabWidth, tabWidth, tabWidth)
		}
		st += ";-webkit-text-size-adjust:none;"
		return "<pre style=\"" + st + "\">"
	}
	cls := h.prefix + "chroma"
	return "<pre class=\"" + cls + "\">"
}

func (h *htmlWriter) writeLine(b *strings.Builder, idx, tabWidth int, wrap bool) {
	o := h.o
	lineNo := idx + o.BaseLine
	hl := h.highlightSet[lineNo]
	if o.LineNumbersInTable {
		return
	}
	if wrap {
		cls := h.prefix + "line"
		if hl {
			cls += " hl"
		}
		b.WriteString("<span class=\"" + cls + "\">")
	}
	if o.LineNumbers {
		if o.LinkableLineNumbers {
			fmt.Fprintf(b, "<span class=\"%sln\" id=\"L%d\"><a class=\"%slnlinks\" href=\"#L%d\">%d</a></span>", h.prefix, lineNo, h.prefix, lineNo, lineNo)
		} else {
			b.WriteString(h.lineNumberSpan(lineNo, false, tabWidth))
		}
	}
	if wrap {
		b.WriteString("<span class=\"" + h.prefix + "cl\">")
	}
	for _, t := range h.lines[idx].tokens {
		value := t.Value
		if tabWidth != 8 {
			value = strings.ReplaceAll(value, "\t", strings.Repeat(" ", tabWidth))
		}
		if h.hasStyle(t.Type) {
			b.WriteString(h.spanOpen(t.Type))
			b.WriteString(escapeHTML(value))
			b.WriteString("</span>")
		} else {
			b.WriteString(escapeHTML(value))
		}
	}
	if wrap {
		b.WriteString("</span>")
	}
	if wrap {
		b.WriteString("</span>")
	}
}

func (h *htmlWriter) lineNumberSpan(n int, hl bool, tabWidth int) string {
	e := h.entry(token.LineNumbers)
	if h.o.LinesStyle != "" {
		if se := style.ParseLinesStyle(h.o.LinesStyle); se != nil {
			e = *se
		}
	}
	if h.o.InlineStyles {
		st := "white-space:pre;-webkit-user-select:none;user-select:none;margin-right:0.4em;padding:0 0.4em 0 0.4em;" + entryInline(e)
		return "<span style=\"" + st + "\">" + strconv.Itoa(n) + "</span>"
	}
	cls := h.prefix + "ln"
	if hl {
		cls += " hl"
	}
	return "<span class=\"" + cls + "\">" + strconv.Itoa(n) + "</span>"
}

func (h *htmlWriter) writeTable(b *strings.Builder, tabWidth int) {
	o := h.o
	if o.InlineStyles {
		b.WriteString("<div style=\"" + entryInline(h.entry(token.PreWrapper)) + ";-webkit-text-size-adjust:none\">\n")
		b.WriteString("<table style=\"border-spacing:0;padding:0;margin:0;border:0;\"><tr><td style=\"vertical-align:top;padding:0;margin:0;border:0\">\n")
		b.WriteString(h.preOpen(tabWidth))
		for i := range h.lines {
			lineNo := i + o.BaseLine
			if h.highlightSet[lineNo] {
				b.WriteString("<span class=\"hl\">")
			}
			b.WriteString(h.tableLineNumberSpan(lineNo, h.highlightSet[lineNo]))
			if h.highlightSet[lineNo] {
				b.WriteString("</span>")
			}
			b.WriteString("\n")
		}
		b.WriteString("</pre></td>\n")
		b.WriteString("<td style=\"vertical-align:top;padding:0;margin:0;border:0;;width:100%\">\n")
		b.WriteString(h.preOpen(tabWidth))
		b.WriteString("<code>")
		for i := range h.lines {
			h.writeLine(b, i, tabWidth, true)
		}
		b.WriteString("</code></pre></td></tr></table>\n")
		b.WriteString("</div>\n")
		return
	}
	b.WriteString("<div class=\"" + h.prefix + "chroma\">\n")
	b.WriteString("<table class=\"" + h.prefix + "lntable\"><tr><td class=\"" + h.prefix + "lntd\">\n")
	b.WriteString(h.preOpen(tabWidth))
	for i := range h.lines {
		lineNo := i + o.BaseLine
		if h.highlightSet[lineNo] {
			b.WriteString("<span class=\"hl\">")
		}
		b.WriteString(h.tableLineNumberSpan(lineNo, h.highlightSet[lineNo]))
		if h.highlightSet[lineNo] {
			b.WriteString("</span>")
		}
		b.WriteString("\n")
	}
	b.WriteString("</pre></td>\n")
	b.WriteString("<td class=\"" + h.prefix + "lntd\">\n")
	b.WriteString(h.preOpen(tabWidth))
	b.WriteString("<code>")
	for i := range h.lines {
		h.writeLine(b, i, tabWidth, true)
	}
	b.WriteString("</code></pre></td></tr></table>\n")
	b.WriteString("</div>\n")
}

func (h *htmlWriter) tableLineNumberSpan(n int, hl bool) string {
	e := h.entry(token.LineNumbersTable)
	if h.o.InlineStyles {
		st := "white-space:pre;-webkit-user-select:none;user-select:none;margin-right:0.4em;padding:0 0.4em 0 0.4em;" + entryInline(e)
		return "<span style=\"" + st + "\">" + strconv.Itoa(n)
	}
	cls := h.prefix + "lnt"
	return "<span class=\"" + cls + "\">" + strconv.Itoa(n) + "\n</span>"
}
