package formatter

import (
	"fmt"
	"strings"

	"chroma/internal/style"
)

// SVG formats tokens as SVG.
func SVG(w *Writer, s *style.Style, tokens []Token, o HTMLOptions) error {
	// Compute the longest line and number of lines
	var sb strings.Builder
	var lines []string
	cur := ""
	for _, t := range tokens {
		v := t.Value
		for {
			i := strings.IndexByte(v, '\n')
			if i < 0 {
				cur += v
				break
			}
			cur += v[:i]
			lines = append(lines, cur)
			cur = ""
			v = v[i+1:]
			if v == "" {
				break
			}
		}
	}
	if cur != "" {
		lines = append(lines, cur)
	}
	maxLen := 0
	for _, l := range lines {
		if n := len([]rune(l)); n > maxLen {
			maxLen = n
		}
	}
	bg := s.Get(token.Background2())
	fg := s.Get(token.Background).Colour
	w.WriteString("<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n")
	w.WriteString("<!DOCTYPE svg PUBLIC \"-//W3C//DTD SVG 1.0//EN\" \"http://www.w3.org/TR/2001/REC-SVG-20010904/DTD/svg10.dtd\">\n")
	fmt.Fprintf(w, "<svg width=\"%dpx\" height=\"%dpx\" xmlns=\"http://www.w3.org/2000/svg\">\n", maxLen*14*3/5+1, (len(lines)+1)*14*12/4)
	w.WriteString("<style>\n@font-face {\n\tfont-family: 'Liberation Mono';\n\tsrc: url(data:application/x-font-woff;charset=utf-8;base64,")
	w.WriteString(svgFont)
	w.WriteString(") format('woff');'\n\tfont-weight: normal;\n\tfont-style: normal;\n}\n</style>")
	fmt.Fprintf(w, "<rect width=\"100%%\" height=\"100%%\" fill=\"%s\"/>\n", bg.Background.Hex())
	fmt.Fprintf(w, "<g font-family=\"Liberation Mono\" font-size=\"14px\" fill=\"%s\">\n", fg.Hex())
	w.WriteString("<text x=\"0\" y=\"1.200000em\" xml:space=\"preserve\">")
	w.WriteString(sb.String())
	w.WriteString("</text>\n</g>\n</svg>\n\n")
	return nil
}
