package colour

import (
	"fmt"
	"math"
	"strconv"
	"strings"
)

// Colour is an RGB colour. The nil (unset) colour is represented by ColourNil.
type Colour int

// ColourNil is the "unset" colour.
const ColourNil Colour = -1

// ParseColour parses a colour from a hex string like "#ff0000" or "#fff".
func ParseColour(s string) (Colour, bool) {
	s = strings.TrimSpace(s)
	if !strings.HasPrefix(s, "#") {
		return ColourNil, false
	}
	h := s[1:]
	switch len(h) {
	case 3:
		v, err := strconv.ParseUint(h, 16, 32)
		if err != nil {
			return ColourNil, false
		}
		r := (v >> 8) & 0xf
		g := (v >> 4) & 0xf
		b := v & 0xf
		return Colour(r<<20 | r<<16 | g<<12 | g<<8 | b<<4 | b), true
	case 6:
		v, err := strconv.ParseUint(h, 16, 32)
		if err != nil {
			return ColourNil, false
		}
		return Colour(v), true
	}
	return ColourNil, false
}

// Red returns the red component.
func (c Colour) Red() int { return (int(c) >> 16) & 0xff }

// Green returns the green component.
func (c Colour) Green() int { return (int(c) >> 8) & 0xff }

// Blue returns the blue component.
func (c Colour) Blue() int { return int(c) & 0xff }

// Hex returns the colour as a 6-digit hex string.
func (c Colour) Hex() string {
	return fmt.Sprintf("#%06x", int(c))
}

// InlineHex returns the shortest hex representation of the colour.
func (c Colour) InlineHex() string {
	r, g, b := c.Red(), c.Green(), c.Blue()
	if r>>4 == r%16 && g>>4 == g%16 && b>>4 == b%16 {
		return fmt.Sprintf("#%x%x%x", r>>4, g>>4, b>>4)
	}
	return fmt.Sprintf("#%02x%02x%02x", r, g, b)
}

// IsNil reports whether the colour is unset.
func (c Colour) IsNil() bool { return c == ColourNil }

// IsZero reports whether the colour is unset.
func (c Colour) IsZero() bool { return c.IsNil() }

// Brighten brightens (factor > 0) or darkens (factor < 0) the colour.
func (c Colour) Brighten(factor float64) Colour {
	r, g, b := float64(c.Red()), float64(c.Green()), float64(c.Blue())
	if factor < 0 {
		f := -factor
		r -= r * f
		g -= g * f
		b -= b * f
	} else {
		r += (255 - r) * factor
		g += (255 - g) * factor
		b += (255 - b) * factor
	}
	return Colour(int(r)<<16 | int(g)<<8 | int(b))
}

// ANSI256 returns the closest ANSI-256 colour index.
func (c Colour) ANSI256() int {
	if v, ok := ansi256ByColour[c]; ok {
		return v
	}
	return nearestANSI256(c)
}

// ANSI16 returns the closest ANSI-16 colour index.
func (c Colour) ANSI16() int {
	if v, ok := ansi16ByColour[c]; ok {
		return v
	}
	return nearestANSI16(c)
}

var ansi256Colours = buildANSI256()

func buildANSI256() [256]Colour {
	var p [256]Colour
	base := []Colour{0x000000, 0x800000, 0x008000, 0x808000, 0x000080, 0x800080, 0x008080, 0xc0c0c0,
