		return fmt.Sprintf("\x1b[38;2;%d;%d;%dm", c.Red(), c.Green(), c.Blue())
	}
	if mode == "terminal256" {
		return fmt.Sprintf("\x1b[38;5;%dm", c.ANSI256())
	}
	i := c.ANSI16()
	if mode == "terminal16" {
		if i < 8 {
			return fmt.Sprintf("\x1b[%dm", 30+i)
		}
		return fmt.Sprintf("\x1b[%dm", 90+i-8)
	}
	if i < 8 {
		return fmt.Sprintf("\x1b[%dm", 30+i)
	}
	return fmt.Sprintf("\x1b[1m\x1b[%dm", 30+i-8)
}

// BgSequence returns the SGR sequence for the background colour in the given mode.
func (c Colour) BgSequence(mode string) string {
	if mode == "terminal16m" {
		return fmt.Sprintf("\x1b[48;2;%d;%d;%dm", c.Red(), c.Green(), c.Blue())
	}
	if mode == "terminal256" {
		return fmt.Sprintf("\x1b[48;5;%dm", c.ANSI256())
	}
	i := c.ANSI16()
	if mode == "terminal16" {
		if i < 8 {
			return fmt.Sprintf("\x1b[%dm", 40+i)
		}
		return fmt.Sprintf("\x1b[%dm", 100+i-8)
	}
	if i < 8 {
		return fmt.Sprintf("\x1b[%dm", 40+i)
	}
	return fmt.Sprintf("\x1b[1m\x1b[%dm", 40+i-8)
}
