allt=json.load(open('/tmp/alltypes.json'))
parents=json.load(open('/tmp/parents.json'))
pseudo=["Background","LineLink","LineTableTD","LineTable","LineHighlight","LineNumbersTable","LineNumbers","Line"]
dumpTypes=pseudo+allt  # types present in the CSS dump (dump list)
dumpSet=set(dumpTypes)
def Z(): return {'color':None,'bg':None,'bold':False,'italic':False,'underline':False}
def h2rgb(h):
    c=h[1:]
    return (int(c[0:2],16),int(c[2:4],16),int(c[4:6],16))
def norm(e):
    e=dict(e)
    if e.get('color') in ('#None','inherit'): e['color']=None
    if e.get('bg')=='#None': e['bg']=None
    return e
# resolved from dump for dump-list types
def resolvedDump(s,t):
    e=css[s]
    if t in dumpSet: return norm(e.get(t,Z()))
    return None
# resolved for the 6 special types from terminal16m
def resolvedSpecial(s,t):
    bg=resolvedDump(s,'Background')
    v=ansi[s].get(t,'')
    seqs=v
    out=Z()
    # parse the concatenated seq string
    i=0
    toks=[]
    while i < len(seqs):
        if seqs.startswith('1',i) and (i+1==len(seqs) or seqs[i+1]=='3' or seqs[i+1]=='4' or seqs[i+1]=='8'):
            out['bold']=True; i+=1
        elif seqs.startswith('4',i) and (i+1==len(seqs) or seqs[i+1]=='8'):
            out['underline']=True; i+=1
        elif seqs.startswith('3',i) and (i+1==len(seqs) or seqs[i+1]=='8'):
            out['italic']=True; i+=1
        elif seqs.startswith('38;2;',i):
            j=i+5; parts=[]
            for _ in range(3):
                k=seqs.index(';',j) if ';' in seqs[j:] else len(seqs)
                parts.append(int(seqs[j:k])); j=k+1
            out['color']='#%02x%02x%02x'%tuple(parts)
            i=j
        elif seqs.startswith('48;2;',i):
            j=i+5; parts=[]
            for _ in range(3):
                k=seqs.index(';',j) if ';' in seqs[j:] else len(seqs)
                parts.append(int(seqs[j:k])); j=k+1
            out['bg']='#%02x%02x%02x'%tuple(parts)
            i=j
        else:
            i+=1
    # remove the background merge
    if out['color'] is not None and bg['color'] is not None and out['color']==bg['color'] and not (out['bold'] and not bg['bold']):
        pass
    if out['color']==bg['color'] and not out['bg'] and not (out['bold'] or out['italic'] or out['underline']):
        out['color']=None
    for k in ('bold','italic','underline'):
        if bg[k]: out[k]=False
    return norm(out)
