{"command": "cat > /workspace/harness.py <<'PYEOF'
#!/usr/bin/env python3
import subprocess, sys, os
ORIG='/workspace/executable'
MINE=os.environ.get('MINE','/tmp/chroma-test')
def run(binary, args, stdin=b''):
    r=subprocess.run([binary]+args, capture_output=True, input=stdin, cwd='/workspace')
    return r.stdout, r.stderr, r.returncode
def cmp(args, stdin=b'', label=None):
    a=run(ORIG,args,stdin); b=run(MINE,args,stdin)
    if a!=b:
        print("DIFF", label or ' '.join(args))
        if a[0]!=b[0]:
            sa=a[0].decode('utf8','replace').split('\n'); sb=b[0].decode('utf8','replace').split('\n')
            for i,(x,y) in enumerate(zip(sa,sb)):
                if x!=y:
                    print("  line %d:\n    orig: %r\n    mine: %r"%(i,x,y)); break
            if len(sa)!=len(sb): print("  len differ", len(sa), len(sb))
        if a[1]!=b[1]: print("  stderr orig=%r mine=%r"%(a[1][:200],b[1][:200]))
        if a[2]!=b[2]: print("  exit orig=%d mine=%d"%(a[2],b[2]))
        return False
    return True
PYEOF
