{"command": "cat > /workspace/src/internal/formatter/simple.go <<'GOEOF'
package formatter

import (
	"fmt"
	"strconv"
	"strings"
	"unicode/utf8"
)

// Noop writes the raw token values.
func Noop(w *Writer, tokens []Token) {
	for _, t := range tokens {
		w.WriteString(t.Value)
	}
}

// Tokens writes tokens in the Go representation form.
func Tokens(w *Writer, tokens []Token) {
	for _, t := range tokens {
		w.WriteString("&Token{")
		w.WriteString(t.Type.String())
		w.WriteString(", ")
		w.WriteString(strconv.Quote(t.Value))
		w.WriteString("}\n")
	}
}

// jsonEscape escapes a string like encoding/json does (with HTML escaping).
func jsonEscape(s string) string {
	var b strings.Builder
	for i := 0; i < len(s); {
		c := s[i]
		if c < 0x80 {
			i++
			switch c {
			case '"':
				b.WriteString("\\\"")
			case '\\':
				b.WriteString("\\\\")
			case '\n':
				b.WriteString("\\n")
			case '\r':
				b.WriteString("\\r")
			case '\t':
				b.WriteString("\\t")
			case '<':
				b.WriteString("\\u003c")
			case '>':
				b.WriteString("\\u003e")
			case '&':
				b.WriteString("\\u0026")
			default:
				if c < 0x20 {
					fmt.Fprintf(&b, "\\u%04x", c)
				} else {
					b.WriteByte(c)
				}
			}
			continue
		}
		r, size := utf8.DecodeRuneInString(s[i:])
		if r == utf8.RuneError && size == 1 {
			b.WriteString("\\ufffd")
			i++
			continue
		}
		b.WriteString(s[i : i+size])
		i += size
	}
	return b.String()
}

// JSON writes tokens as a JSON array.
func JSON(w *Writer, tokens []Token) {
	w.WriteString("[\n")
	for i, t := range tokens {
		w.WriteString("  {\"type\":")
		w.WriteString(jsonEscape(t.Type.String()))
		w.WriteString(",\"value\":")
		w.WriteString(jsonEscape(t.Value))
		w.WriteString("}")
		if i < len(tokens)-1 {
			w.WriteString(",")
		}
		w.WriteString("\n")
	}
	w.WriteString("]\n")
}

// IndentTabs replaces tabs with spaces.
func IndentTabs(s string, tabWidth int) string {
	if tabWidth <= 0 {
		return s
	}
	return strings.ReplaceAll(s, "\t", strings.Repeat(" ", tabWidth))
