package formatter

import (
	"fmt"
	"strconv"
	"strings"
	"unicode/utf8"
)

// Noop writes the raw token values.
func Noop(w *Writer, tokens []Token) {
	for _, t := range tokens {
		w.WriteString(t.Value)
	}
}

// Tokens writes tokens in the Go representation form.
func Tokens(w *Writer, tokens []Token) {
	for _, t := range tokens {
		w.WriteString("&Token{")
		w.WriteString(t.Type.String())
		w.WriteString(", ")
		w.WriteString(strconv.Quote(t.Value))
		w.WriteString("}\n")
	}
}

// jsonEscape escapes a string like encoding/json does (with HTML escaping).
func jsonEscape(s string) string {
	var b strings.Builder
	for i := 0; i < len(s); {
		c := s[i]
		if c < 0x80 {
			i++
			switch c {
			case '"':
				b.WriteString("\\\"")
			case '\\':
				b.WriteString("\\\\")
			case '\n':
				b.WriteString("\\n")
			case '\r':
				b.WriteString("\\r")
			case '\t':
				b.WriteString("\\t")
			case '<':
				b.WriteString("\\u003c")
			case '>':
				b.WriteString("\\u003e")
			case '&':
				b.WriteString("\\u0026")
			default:
				if c < 0x20 {
					fmt.Fprintf(&b, "\\u%04x", c)
				} else {
					b.WriteByte(c)
				}
			}
			continue
