		if r == utf8.RuneError && size == 1 {
			b.WriteString("\\ufffd")
			i++
			continue
		}
		b.WriteString(s[i : i+size])
		i += size
	}
	return b.String()
}

// JSON writes tokens as a JSON array.
func JSON(w *Writer, tokens []Token) {
	w.WriteString("[\n")
	for i, t := range tokens {
		w.WriteString("  {\"type\":")
		w.WriteString(jsonEscape(t.Type.String()))
		w.WriteString(",\"value\":")
		w.WriteString(jsonEscape(t.Value))
		w.WriteString("}")
		if i < len(tokens)-1 {
			w.WriteString(",")
		}
		w.WriteString("\n")
	}
	w.WriteString("]\n")
}

