allt=json.load(open('/tmp/alltypes.json'))
inp=open('/tmp/in83.txt','rb').read()
def toks(s):
    segs=[];pos=0
    for m in re.finditer(r'\x1b\[[0-9;]*m', s):
        if m.start()>pos: segs.append(('T', s[pos:m.start()]))
        segs.append(('S', m.group())); pos=m.end()
    if pos<len(s): segs.append(('T', s[pos:]))
    return segs
def parse(out):
    segs=toks(out.decode())
    idx=0; cur=[]; m={}
    for k,v in segs:
        if k=='S':
            if v=='\x1b[0m': cur=[]
            else: cur.append(v[2:-1])
        else:
            for ch in v:
                if idx<len(allt): m[allt[idx]]=list(cur)
                idx+=1
    return m
for s in ['aura-theme-dark','catppuccin-mocha','evergarden','gruvbox','doom-one','onedark','pygments','rrt','trac','kanagawa-lotus','paraiso-light','perldoc','rainbow_dash']:
